"""Shipping helpers for task D2."""


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    JP -> 1, KR or SG -> 2, anything else -> 3.
    """
    if country_code == "JP":
        return 1
    if country_code in ("KR", "SG"):
        return 2
    return 3


_BASE_BY_ZONE = {1: 4.5, 2: 9.0, 3: 20.0}


def shipping_cost(weight_kg, zone):
    """Return base + 1.2 * weight_kg, rounded to 2 decimals.

    Base is 4.5 for zone 1, 9.0 for zone 2, 20.0 for zone 3.
    """
    base = _BASE_BY_ZONE[zone]
    return round(base + 1.2 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 150 or l + w + h exceeds 360."""
    return l > 150 or w > 150 or h > 150 or (l + w + h) > 360

